actions.script:
import java.math.RoundingMode
import java.util.Calendar
import groovy.json.JsonOutput
org = posOrganizationPartyId
if (!org || org == '_NA_') org = null

def inr = { amt, dec = 2 ->
    def n = ((amt ?: 0) as BigDecimal).setScale(dec, RoundingMode.HALF_UP)
    def neg = n.signum() < 0; n = n.abs()
    def intPart = n.toBigInteger().toString()
    def res
    if (intPart.length() <= 3) { res = intPart }
    else {
        def last3 = intPart.substring(intPart.length() - 3)
        def rest = intPart.substring(0, intPart.length() - 3)
        def sb = new StringBuilder()
        while (rest.length() > 2) { sb.insert(0, ',' + rest.substring(rest.length() - 2)); rest = rest.substring(0, rest.length() - 2) }
        sb.insert(0, rest); res = sb.toString() + ',' + last3
    }
    def out = (neg ? '-' : '') + '₹' + res
    if (dec > 0) { def frac = n.remainder(BigDecimal.ONE).movePointRight(dec).toBigInteger().toString().padLeft(dec, '0'); out += '.' + frac }
    return out
}

def now = ec.user.nowTimestamp
def sdf = new java.text.SimpleDateFormat('yyyy-MM-dd'); sdf.setTimeZone(ec.user.timeZone)
def todayStr = sdf.format(now)
def selectedDay
try { selectedDay = java.time.LocalDate.parse((ec.context.dashDate ?: todayStr).toString()) }
catch (java.time.format.DateTimeParseException ignored) { selectedDay = java.time.LocalDate.parse(todayStr) }
dashDate = selectedDay.toString()
def midnight = { date -> ec.l10n.parseTimestamp(date.toString() + ' 00:00:00', 'yyyy-MM-dd HH:mm:ss') }
def dayStart = midnight(dashDate)
def nextDayStart = midnight(selectedDay.plusDays(1))
def yStart = midnight(selectedDay.minusDays(1))

// Limit standalone KOT reporting to sales linked to a ticket in the same organization.
def kotOnly = kitchenModuleId == 'kot'
def shop = kotOnly ? ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope')
    .parameter('includePosScope',true).call() : null
def terminals = shop?.activeShopId ? (shop.terminalIds ?: []) : null
def terminalRestricted = kotOnly && posTerminalRestricted &&
    !['ZENITH_STORE_MGR','ZENITH_MULTI_SHOP_MANAGER'].any { ec.user.isInGroup(it) }
if (terminalRestricted) {
    def shopTerminals = terminals
    terminals = (posAllowedTerminalIds ?: []).findAll { shopTerminals == null || shopTerminals.contains(it) }
}
def salesEntity = !kotOnly ? 'zenith.erp.pos.PosTransaction' :
    (terminals != null ? 'zenith.erp.pos.KotTransactionDetailView' : 'zenith.erp.pos.KotTransactionView')
def amt = { t -> (t.payableAmount == null ? (t.grandTotal ?: 0) : t.payableAmount) as BigDecimal }
def findOrders = { startInclusive, endExclusive, completedOnly ->
    def f = ec.entity.find(salesEntity)
        .condition('entryDate', 'greater-equals', startInclusive).condition('entryDate', 'less', endExclusive)
        .condition('organizationPartyId', org ?: '__NO_ORGANIZATION__')
        .selectFields(['transactionId', 'entryDate', 'statusId', 'customerPartyId', 'payableAmount', 'grandTotal'])
    if (completedOnly) f.condition('statusId', 'PtCompleted')
    if (kotOnly) {
        // Moqui omits view members with no selected or filtered aliases.
        f.condition('kotOrganizationPartyId',org ?: '__NO_ORGANIZATION__').distinct(true)
        if (terminals != null) f.condition('terminalId','in',terminals ?: ['__NONE__'])
        if (terminalRestricted) f.condition('operatorPartyId',ec.user.userAccount?.partyId ?: '__NONE__')
    }
    return f.orderBy('entryDate').list()
}

def todayOrders = findOrders(dayStart, nextDayStart, false)
completedTxns = todayOrders.findAll { it.statusId == 'PtCompleted' }
def totalSalesAmt = completedTxns.sum { amt(it) } ?: BigDecimal.ZERO
completedOrders = completedTxns.size()
def isWalkIn = { t -> !t.customerPartyId || t.customerPartyId == 'WALKIN_' + org }
customers = completedTxns.count(isWalkIn)
def avgOrderAmt = completedOrders > 0 ? (totalSalesAmt / completedOrders).setScale(2, RoundingMode.HALF_UP) : BigDecimal.ZERO
def hoursElapsed = 24
if (dashDate == todayStr) { def hc = Calendar.getInstance(ec.user.timeZone); hc.setTime(now); hoursElapsed = hc.get(Calendar.HOUR_OF_DAY) + 1 }
def findActiveKots = {
    def f = ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('statusId', 'in', ['KotNew', 'KotPreparing', 'KotReady'])
        .condition('organizationPartyId', org ?: '__NO_ORGANIZATION__')
    if (terminals != null) f.condition('terminalId','in',terminals ?: ['__NONE__'])
    f
}
def countUnbilled = { start, end -> findActiveKots().condition('transactionId', null)
    .condition('kotDate', 'greater-equals', start).condition('kotDate', 'less', end).count() }
ordersInProgress = findActiveKots().count()
totalOrdersAll = todayOrders.size() + (kotOnly ? countUnbilled(dayStart, nextDayStart) : 0)
def ophAmt = ((kotOnly ? totalOrdersAll : completedOrders) as BigDecimal).divide(hoursElapsed as BigDecimal, 1, RoundingMode.HALF_UP)

// yesterday
def yOrders = findOrders(yStart, dayStart, false)
def yTxns = yOrders.findAll { it.statusId == 'PtCompleted' }
def ySales = yTxns.sum { amt(it) } ?: BigDecimal.ZERO
def yCompleted = yTxns.size()
def yAll = yOrders.size() + (kotOnly ? countUnbilled(yStart, dayStart) : 0)
def yCustomers = yTxns.count(isWalkIn)
def yAov = yCompleted > 0 ? (ySales / yCompleted) : BigDecimal.ZERO
def yOph = ((kotOnly ? yAll : yCompleted) as BigDecimal).divide(24 as BigDecimal, 1, RoundingMode.HALF_UP)

def delta = { cur, prev ->
    cur = (cur ?: 0) as BigDecimal; prev = (prev ?: 0) as BigDecimal
    if (prev == 0) return [has: false]
    def d = ((cur - prev) * 100 / prev).setScale(1, RoundingMode.HALF_UP)
    return [has: true, up: (d.signum() >= 0), txt: d.abs().toPlainString()]
}
dSales = delta(totalSalesAmt, ySales)
dCompleted = delta(completedOrders, yCompleted)
dCustomers = delta(customers, yCustomers)
dTotalOrders = delta(totalOrdersAll, yAll)
dAov = delta(avgOrderAmt, yAov)
dOph = delta(ophAmt, yOph)

totalSales = inr(totalSalesAmt, 2)
avgOrderStr = inr(avgOrderAmt, 2)
ordersPerHourStr = ophAmt.toPlainString()

// payment breakdown
def txnIds = completedTxns.collect { it.transactionId }
def payments = txnIds ? ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId', 'in', txnIds).list() : []
def pmColor = ['UPI':'var(--kd-pri)', 'Cash':'var(--kd-grnt)', 'Card':'var(--kd-orange)', 'Wallet':'var(--kd-blue)', 'BankTransfer':'#60A5FA', 'Cheque':'#9CA3AF', 'Credit':'var(--kd-redt)', 'Other':'#9CA3AF']
def pmTotals = new LinkedHashMap()
payments.each { p -> def m = p.paymentMethod ?: 'Other'; pmTotals[m] = (pmTotals[m] ?: BigDecimal.ZERO) + ((p.amount ?: 0) as BigDecimal) }
def totalPay = pmTotals.values().sum() ?: BigDecimal.ZERO
paymentBars = (pmColor.keySet() + pmTotals.keySet()).unique().findAll { pmTotals.containsKey(it) }.collect { method ->
    def amount = pmTotals[method]
    def pct = totalPay > 0 ? (amount * 100.0 / totalPay) : 0.0
    [method: (method + ' Payments'), amount: inr(amount, 2),
     pct: (new BigDecimal(pct)).setScale(1, RoundingMode.HALF_UP).toPlainString(),
     color: (pmColor[method] ?: '#9CA3AF')]
}

// chart series
def hourLabel = { h ->
    def f1 = h % 12; if (f1 == 0) f1 = 12; def a1 = h < 12 ? 'AM' : 'PM'
    def h2 = (h + 1) % 24; def f2 = h2 % 12; if (f2 == 0) f2 = 12; def a2 = h2 < 12 ? 'AM' : 'PM'
    return f1 + ' ' + a1 + ' – ' + f2 + ' ' + a2
}
def point = { label, txns -> [label:label, sales:txns.sum { amt(it) } ?: 0, orders:txns.size()] }
def hourly = completedTxns.groupBy { t ->
    def c = Calendar.getInstance(ec.user.timeZone); c.setTime(t.entryDate); c.get(Calendar.HOUR_OF_DAY)
}
def daily = findOrders(midnight(selectedDay.minusDays(29)), nextDayStart, true).groupBy { sdf.format(it.entryDate) }
def dlabel = java.time.format.DateTimeFormatter.ofPattern('d MMM', ec.user.locale)
def monthPoints = (29..0).collect { offset ->
    def day = selectedDay.minusDays(offset)
    point(day.format(dlabel), daily[day.toString()] ?: [])
}
chartJson = JsonOutput.toJson([
    today: [points:(0..23).collect { point(hourLabel(it), hourly[it] ?: []) },
            axis:['12 AM', '4 AM', '8 AM', '12 PM', '4 PM', '8 PM', '12 AM']],
    week: [points:monthPoints[23..29], axis:monthPoints[23..29]*.label],
    month: [points:monthPoints, axis:[0, 5, 10, 15, 20, 25, 29].collect { monthPoints[it].label }]
])

// top 5 dishes
def items = txnIds ? ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId', 'in', txnIds).list() : []
def pmap = [:]
items.each { i ->
    def k = i.productId ?: i.productName
    if (!pmap[k]) pmap[k] = [name: i.productName ?: i.productId ?: 'Unnamed item', qty: BigDecimal.ZERO, total: BigDecimal.ZERO]
    pmap[k].qty += ((i.quantity ?: 0) as BigDecimal); pmap[k].total += ((i.lineTotal ?: 0) as BigDecimal)
}
dishes = pmap.values().sort { a, b -> (b.total <=> a.total) ?: (b.qty <=> a.qty) ?: (a.name <=> b.name) }.collect { d ->
    [name: d.name, plates: d.qty.stripTrailingZeros().toPlainString(), revenue: inr(d.total, 2)]
}

def lblFmt = new java.text.SimpleDateFormat('d MMM yyyy'); lblFmt.setTimeZone(ec.user.timeZone)
dateLabel = (dashDate == todayStr ? 'Today, ' : '') + lblFmt.format(dayStart)
isToday = dashDate == todayStr
copyrightYear = java.time.LocalDate.parse(todayStr).year
